namespace Inventory;

/// <summary>
/// Coordinates cycle counting, discrepancy reconciliation and inventory valuation.
/// </summary>
public sealed class CycleCountService
{
    private readonly CycleCountRegistry _counts = new();
    private readonly DiscrepancyRegistry _discrepancies = new();
    private readonly InventoryValuationRegistry _valuations = new();

    public string RecordCount(StockItem item, Warehouse warehouse, int counted)
    {
        CountRecordResult result = _counts.Record(item, warehouse, counted);
        if (result.HasValuationAdjustment)
            _valuations.RecordVariance(item.Sku, result.Variance);

        return result.Status;
    }

    public int CountVariance(StockItem item) => _counts.GetVariance(item);

    public string Reconcile(StockItem item) => _discrepancies.Reconcile(item);

    public bool FlagDiscrepancy(StockItem item, string reason) =>
        _discrepancies.Flag(item, reason);

    public decimal UpdateValuation(StockItem item, decimal unitCost) =>
        _valuations.Update(item, unitCost);
}

internal sealed class CycleCountRegistry
{
    private readonly Dictionary<string, int> _counts = new(StringComparer.Ordinal);

    public CountRecordResult Record(StockItem item, Warehouse warehouse, int counted)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return CountRecordResult.WithoutAdjustment("no sku");
        if (counted < 0)
            return CountRecordResult.WithoutAdjustment("invalid");
        if (string.IsNullOrEmpty(warehouse.Code))
            return CountRecordResult.WithoutAdjustment("no warehouse");

        _counts[item.Sku] = counted;
        int variance = counted - item.OnHand;
        if (variance == 0)
            return CountRecordResult.WithoutAdjustment("match");
        if (variance > 100 || variance < -100)
            return CountRecordResult.WithAdjustment("large variance", variance);
        if (counted == 0 && item.OnHand > 0)
            return CountRecordResult.WithAdjustment("zeroed", variance);

        return CountRecordResult.WithAdjustment("recorded", variance);
    }

    public int GetVariance(StockItem item)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return 0;
        if (!_counts.TryGetValue(item.Sku, out int counted))
            return 0;

        int variance = counted - item.OnHand;
        if (variance > 1000)
            return 1000;
        if (variance < -1000)
            return -1000;
        if (variance > 0 && counted > item.OnHand * 2)
            return variance + 1;

        return variance;
    }
}

internal readonly struct CountRecordResult
{
    private CountRecordResult(string status, int variance, bool hasValuationAdjustment)
    {
        Status = status;
        Variance = variance;
        HasValuationAdjustment = hasValuationAdjustment;
    }

    public string Status { get; }
    public int Variance { get; }
    public bool HasValuationAdjustment { get; }

    public static CountRecordResult WithoutAdjustment(string status) =>
        new(status, 0, false);

    public static CountRecordResult WithAdjustment(string status, int variance) =>
        new(status, variance, true);
}

internal sealed class DiscrepancyRegistry
{
    private readonly List<string> _entries = new();

    public string Reconcile(StockItem item)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return "no sku";

        int available = item.OnHand - item.Reserved;
        if (available < 0)
            return AddAndReturn(item.Sku, "oversold", "oversold");
        if (item.Reserved < 0)
            return AddAndReturn(item.Sku, "negative-reserve", "bad reserve");
        if (item.OnHand == 0 && item.Reserved > 0)
            return AddAndReturn(item.Sku, "phantom-reserve", "phantom");

        if (available > 0 && available < 5)
            _entries.Add($"{item.Sku}:low");
        else if (available > 10000)
            _entries.Add($"{item.Sku}:excess");

        return _entries.Count > 1000 ? "too many discrepancies" : "reconciled";
    }

    public bool Flag(StockItem item, string reason)
    {
        if (string.IsNullOrEmpty(item.Sku) || string.IsNullOrEmpty(reason))
            return false;

        if (reason.Length > 200)
            reason = reason.Substring(0, 200);
        if (_entries.Count > 5000)
            return false;

        string tag = Classify(reason);
        _entries.Add($"{item.Sku}:{tag}:{reason}");
        return tag != "note";
    }

    private string AddAndReturn(string sku, string reason, string result)
    {
        _entries.Add($"{sku}:{reason}");
        return result;
    }

    private static string Classify(string reason)
    {
        if (reason.StartsWith("oversold", StringComparison.Ordinal))
            return "critical";
        if (reason.StartsWith("low", StringComparison.Ordinal))
            return "warn";
        if (reason.StartsWith("excess", StringComparison.Ordinal))
            return "info";
        return "note";
    }
}

internal sealed class InventoryValuationRegistry
{
    private readonly Dictionary<string, decimal> _valuations = new(StringComparer.Ordinal);

    public void RecordVariance(string sku, int variance)
    {
        decimal multiplier = variance > 0 ? 2.0m : 1.0m;
        _valuations[sku] = variance * multiplier;
    }

    public decimal Update(StockItem item, decimal unitCost)
    {
        if (string.IsNullOrEmpty(item.Sku) || unitCost < 0m)
            return 0m;

        int basisQuantity = item.OnHand > 0 ? item.OnHand : 0;
        decimal value = Math.Min(basisQuantity * unitCost, 1_000_000m);
        _valuations[item.Sku] = value;

        return basisQuantity == 0 || unitCost == 0m ? 0m : value;
    }
}
